// src/middleware/auth.ts
async function authenticate(request, reply) {
  try {
    await request.jwtVerify();
    const payload = request.user;
    if (!payload?.id) {
      return reply.status(401).send({ error: "Non authentifi\xE9" });
    }
    const db = getDb();
    const [user] = await db.select({
      id: users.id,
      email: users.email,
      name: users.name,
      role: users.role
    }).from(users).where(eq(users.id, payload.id)).limit(1);
    if (!user) {
      return reply.status(401).send({ error: "Utilisateur introuvable" });
    }
    request.user = {
      id: user.id,
      email: user.email,
      name: user.name,
      role: user.role
    };
  } catch {
    return reply.status(401).send({ error: "Token invalide ou expir\xE9" });
  }
}
function requireRole(...roles2) {
  return async (request, reply) => {
    const userRole = request.user?.role;
    if (!userRole || !roles2.includes(userRole)) {
      return reply.status(403).send({
        error: "Acc\xE8s refus\xE9 : r\xF4le insuffisant",
        allowedRoles: roles2
      });
    }
  };
}

