function parseCsv(text3) {
  let t = text3;
  if (t.charCodeAt(0) === 65279) t = t.slice(1);
  t = t.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  const lines = t.split("\n").map((l) => l.trim()).filter(Boolean);
  if (lines.length < 2) return [];
  const headers = splitCsvLine(lines[0]).map((h) => h.trim());
  const result = [];
  for (let i = 1; i < lines.length; i++) {
    const values = splitCsvLine(lines[i]);
    const row = {};
    headers.forEach((h, j) => {
      row[h] = (values[j] ?? "").trim();
    });
    result.push(row);
  }
  return result;
}
function splitCsvLine(line2) {
  const result = [];
  let current = "";
  let inQuotes = false;
  for (let i = 0; i < line2.length; i++) {
    const ch = line2[i];
    if (ch === '"') {
      if (inQuotes && line2[i + 1] === '"') {
        current += '"';
        i++;
      } else inQuotes = !inQuotes;
    } else if (ch === "," && !inQuotes) {
      result.push(current);
      current = "";
    } else current += ch;
  }
  result.push(current);
  return result;
}

