async function recalcClientDebt(db, clientId) {
  const [client2] = await db.select({ monthlyFee: clients.monthlyFee }).from(clients).where(eq(clients.id, clientId)).limit(1);
  if (!client2) return;
  const paidRows = await db.select({ total: payments.amount }).from(payments).where(eq(payments.clientId, clientId));
  const totalPaid = paidRows.reduce((sum, p) => sum + Number(p.total), 0);
  const monthlyFee = Number(client2.monthlyFee);
  const debt = Math.max(0, monthlyFee - totalPaid);
  await db.update(clients).set({
    debt: String(debt),
    paymentStatus: totalPaid >= monthlyFee ? "paye" : "impaye",
    overdue: totalPaid < monthlyFee && monthlyFee > 0
  }).where(eq(clients.id, clientId));
}

