async function reminderRoutes(app) {
  app.get("/", { preHandler: [authenticate] }, async (request) => {
    const query = request.query;
    const db = getDb();
    if (query.pending === "true") {
      return db.select().from(reminders).where(eq(reminders.sent, false)).orderBy(desc(reminders.remindAt));
    }
    return db.select().from(reminders).orderBy(desc(reminders.createdAt));
  });
  app.post("/", { preHandler: [authenticate, requireRole("directeur", "responsable")] }, async (request, reply) => {
    const schema = external_exports.object({
      eventId: external_exports.string().optional(),
      targetType: external_exports.string().optional().default("user"),
      targetId: external_exports.string().optional().default(""),
      title: external_exports.string().min(1),
      message: external_exports.string().optional().default(""),
      remindAt: external_exports.string().min(1),
      method: external_exports.enum(["in_app", "email"]).optional().default("in_app")
    });
    const input = schema.parse(request.body);
    const db = getDb();
    const [reminder] = await db.insert(reminders).values({ ...input, remindAt: new Date(input.remindAt) }).returning();
    return reminder;
  });
  app.post("/from-event/:eventId", { preHandler: [authenticate, requireRole("directeur", "responsable")] }, async (request, reply) => {
    const { eventId } = request.params;
    const schema = external_exports.object({
      minutesBefore: external_exports.number().min(1).max(10080),
      method: external_exports.enum(["in_app", "email"]).optional().default("in_app")
    });
    const input = schema.parse(request.body);
    const db = getDb();
    const [event] = await db.select().from(events).where(eq(events.id, eventId)).limit(1);
    if (!event) return reply.status(404).send({ error: "\xC9v\xE9nement introuvable" });
    const eventDate = /* @__PURE__ */ new Date(`${event.date}T${event.startTime}`);
    const remindAt = new Date(eventDate.getTime() - input.minutesBefore * 6e4);
    const [reminder] = await db.insert(reminders).values({
      eventId,
      title: `Rappel: ${event.title}`,
      message: `L'\xE9v\xE9nement "${event.title}" commence dans ${input.minutesBefore} minutes.`,
      remindAt,
      method: input.method
    }).returning();
    return reminder;
  });
  app.post("/process", { preHandler: [authenticate, requireRole("directeur", "superadmin")] }, async () => {
    const db = getDb();
    const now = /* @__PURE__ */ new Date();
    const due = await db.select().from(reminders).where(and(eq(reminders.sent, false), lt(reminders.remindAt, now))).limit(50);
    for (const r of due) {
      if (r.method === "in_app") {
        await db.insert(notifications).values({
          userId: r.targetId || void 0,
          type: "reminder",
          title: r.title,
          message: r.message,
          link: `/dashboard/calendar`
        });
      }
      await db.update(reminders).set({ sent: true }).where(eq(reminders.id, r.id));
    }
    return { processed: due.length };
  });
  app.delete("/:id", { preHandler: [authenticate, requireRole("directeur")] }, async (request, reply) => {
    const { id } = request.params;
    const db = getDb();
    await db.delete(reminders).where(eq(reminders.id, id));
    return { ok: true };
  });
}

// src/routes/reports.ts
async function reportRoutes(app) {
  app.get("/operational", { preHandler: [authenticate, requireRole("directeur", "superadmin")] }, async () => {
    const db = getDb();
    const today = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
    const firstOfMonth = new Date((/* @__PURE__ */ new Date()).getFullYear(), (/* @__PURE__ */ new Date()).getMonth(), 1).toISOString().slice(0, 10);
    const [
      { count: totalEtudiants },
      { count: totalFormateurs },
      { count: examensPlanifies },
      { count: bulletinsAPublier },
      { count: stagesEnCours },
      { count: seancesAujourdhui },
      paiementsDuMois,
      etuStats
    ] = await Promise.all([
      db.select({ count: sql`count(*)::int` }).from(etudiants).then((r) => r[0]),
      db.select({ count: sql`count(*)::int` }).from(formateurs).then((r) => r[0]),
      db.select({ count: sql`count(*)::int` }).from(examens).where(eq(examens.statut, "planifie")).then((r) => r[0]),
      db.select({ count: sql`count(*)::int` }).from(bulletins).where(ne(bulletins.statut, "publie")).then((r) => r[0]),
      db.select({ count: sql`count(*)::int` }).from(stages).where(sql`${stages.statut} IN ('en_cours','soutenance')`).then((r) => r[0]),
      db.select({ count: sql`count(*)::int` }).from(seances).where(eq(seances.date, today)).then((r) => r[0]),
      db.select({ montant: historiquePaiements.montant }).from(historiquePaiements).where(gte(historiquePaiements.date, firstOfMonth)).then((r) => r),
      db.select({ statut: etudiants.statut, count: sql`count(*)::int` }).from(etudiants).groupBy(etudiants.statut)
    ]);
    const paiementsMois = paiementsDuMois.reduce((s, p) => s + Number(p.montant), 0);
    const parStatut = {};
    for (const s of etuStats) parStatut[s.statut] = s.count;
    return {
      date: today,
      resume: {
        totalEtudiants,
        totalFormateurs,
        examensPlanifies,
        bulletinsAPublier,
        stagesEnCours,
        seancesAujourdhui,
        encaisseCeMois: paiementsMois
      },
      repartitionEtudiants: parStatut
    };
  });
  app.get("/financial", { preHandler: [authenticate, requireRole("directeur", "superadmin")] }, async () => {
    const db = getDb();
    const allPaiements = await db.select().from(historiquePaiements).orderBy(desc(historiquePaiements.date));
    const allEtudiants = await db.select({ fraisAnnuels: etudiants.fraisAnnuels, resteAPayer: etudiants.resteAPayer, statut: etudiants.statut, paiement: etudiants.paiement }).from(etudiants);
    const totalEncaisse = allPaiements.reduce((s, p) => s + Number(p.montant), 0);
    const totalDu = allEtudiants.reduce((s, e) => s + Number(e.fraisAnnuels), 0);
    const totalReste = allEtudiants.reduce((s, e) => s + Number(e.resteAPayer), 0);
    const tauxRecouvrement = totalDu > 0 ? Math.round(totalEncaisse / totalDu * 100) : 0;
    const paiementsParMois = {};
    for (const p of allPaiements) {
      const mois = p.date.slice(0, 7);
      paiementsParMois[mois] = (paiementsParMois[mois] || 0) + Number(p.montant);
    }
    return {
      totalEncaisse,
      totalDu,
      totalReste,
      tauxRecouvrement,
      paiementsParMois,
      etudiants: {
        total: allEtudiants.length,
        aJour: allEtudiants.filter((e) => e.paiement === "paye").length,
        enRetard: allEtudiants.filter((e) => e.paiement === "retard").length,
        impaye: allEtudiants.filter((e) => e.paiement === "impaye").length
      }
    };
  });
  app.get("/academic", { preHandler: [authenticate, requireRole("directeur", "superadmin", "responsable")] }, async () => {
    const db = getDb();
    const [examensData, bulletinsData, stagesData, seancesData] = await Promise.all([
      db.select({ statut: examens.statut, count: sql`count(*)::int` }).from(examens).groupBy(examens.statut),
      db.select({ statut: bulletins.statut, count: sql`count(*)::int` }).from(bulletins).groupBy(bulletins.statut),
      db.select({ statut: stages.statut, count: sql`count(*)::int` }).from(stages).groupBy(stages.statut),
      db.select({ count: sql`count(*)::int` }).from(seances)
    ]);
    const parExamen = {};
    for (const e of examensData) parExamen[e.statut] = e.count;
    const parBulletin = {};
    for (const b of bulletinsData) parBulletin[b.statut] = b.count;
    const parStage = {};
    for (const s of stagesData) parStage[s.statut] = s.count;
    return {
      examens: { total: examensData.reduce((s, e) => s + e.count, 0), parStatut: parExamen },
      bulletins: { total: bulletinsData.reduce((s, b) => s + b.count, 0), parStatut: parBulletin },
      stages: { total: stagesData.reduce((s, st) => s + st.count, 0), parStatut: parStage },
      seances: { total: seancesData[0]?.count ?? 0 }
    };
  });
}

// src/routes/notes.ts
var createNoteSchema = external_exports.object({
  etudiantId: external_exports.string().uuid(),
  module: external_exports.string().min(1, "Module requis"),
  note: external_exports.number().min(0).max(20, "La note doit \xEAtre entre 0 et 20"),
  coef: external_exports.number().min(0).optional().default(3),
  credits: external_exports.number().min(0).optional().default(6),
  examen: external_exports.string().optional().default("")
});
function ponderee2(notes) {
  let total = 0;
  let totalCoef = 0;
  for (const n of notes) {
    total += Number(n.note) * Number(n.coef);
    totalCoef += Number(n.coef);
  }
  return totalCoef > 0 ? Math.round(total / totalCoef * 100) / 100 : 0;
}
async function recalculerMoyenne(db, etudiantId) {
  const all = await db.select({ note: notesEtudiant.note, coef: notesEtudiant.coef }).from(notesEtudiant).where(eq(notesEtudiant.etudiantId, etudiantId));
  const moyenne = ponderee2(all);
  await db.update(etudiants).set({ moyenne: String(moyenne) }).where(eq(etudiants.id, etudiantId));
  return moyenne;
}
async function noteRoutes(app) {
  app.post(
    "/",
    { preHandler: [authenticate, requireRole("directeur", "enseignant", "responsable")] },
    async (request) => {
      const input = createNoteSchema.parse(request.body);
      const db = getDb();
      const [existing] = await db.select().from(notesEtudiant).where(
        and(
          eq(notesEtudiant.etudiantId, input.etudiantId),
          eq(notesEtudiant.module, input.module)
        )
      ).limit(1);
      if (existing) {
        const [updated] = await db.update(notesEtudiant).set({
          note: String(input.note),
          coef: String(input.coef),
          credits: String(input.credits),
          examen: input.examen
        }).where(eq(notesEtudiant.id, existing.id)).returning();
        await recalculerMoyenne(db, input.etudiantId);
        return updated;
      }
      const [created] = await db.insert(notesEtudiant).values({
        etudiantId: input.etudiantId,
        module: input.module,
        note: String(input.note),
        coef: String(input.coef),
        credits: String(input.credits),
        examen: input.examen
      }).returning();
      await recalculerMoyenne(db, input.etudiantId);
      return created;
    }
  );
  app.delete(
    "/:id",
    { preHandler: [authenticate, requireRole("directeur", "enseignant", "responsable")] },
    async (request, reply) => {
      const { id } = request.params;
      const db = getDb();
      const [note] = await db.select().from(notesEtudiant).where(eq(notesEtudiant.id, id)).limit(1);
      if (!note) return reply.status(404).send({ error: "Note introuvable" });
      await db.delete(notesEtudiant).where(eq(notesEtudiant.id, id));
      await recalculerMoyenne(db, note.etudiantId);
      return { ok: true };
    }
  );
}

