var appPromise;
function getApp() {
  if (!appPromise) {
    appPromise = buildApp().then((app) => app.ready().then(() => app));
    appPromise.catch(() => {
      appPromise = void 0;
    });
  }
  return appPromise;
}
async function handler(req, res) {
  const app = await getApp();
  app.server.emit("request", req, res);
}
export {
  handler as default
};
